// fdk-aac-rs: Third-Party Modified Version of the Fraunhofer FDK AAC Codec Library for Android.
// A Rust port of fdk-aac 2.0.3. See LICENSE.txt for the complete license text.
//
// Ported from libSACdec/src/sac_calcM1andM2.h, libSACdec/src/sac_calcM1andM2.cpp.

//! Port of `sac_calcM1andM2.h` and `sac_calcM1andM2.cpp`: the calculation of the upmix
//! matrices M1 and M2 (only M2 is used by the 212 tree).
//!
//! The file-static tables are generated by `sac_rom/gen_tables.py` ([`tables`]).
//!
//! # Undefined behavior
//!
//! `param2UMX_Prediction_Core__FDK()` (inlined into `param2UMX_Prediction__FDK()` in the
//! reference) computes `sqrt_CLD_e[cldIdx] << 1` with negative values (a plain shift in both
//! builds) and uses `fAddNorm()` and `scaleValue()`, whose shift amounts stay small for the
//! table values (the exponents of all mantissas are bounded by the tables). All inputs of the
//! function are table indices (`cldIdx` 0..=30, `iccIdx` 0..=7, `ipdIdx` 0..=15), so the
//! `cref` test covers every combination through the library's own
//! `SpatialDecCalculateM1andM2()`.

pub mod tables;
pub use tables::*;

use fdk_aac_rs_fdk::common_fix::*;
use fdk_aac_rs_fdk::fdk_assert;

use crate::sac_dec::*;
use crate::sac_dec_interface::*;
use crate::sac_rom::*;
use crate::sac_smoothing::spatial_dec_smooth_opd;

/// `SCALE_PARAM_M1`
pub const SCALE_PARAM_M1: i32 = 3;
/// `SCALE_PARAM_CALC_M2`: scaling of the M2 matrix, but only for the binaural upmix type.
pub const SCALE_PARAM_CALC_M2: i32 = 3;
/// `SCALE_PARAM_M2_515X`
pub const SCALE_PARAM_M2_515X: i32 = 3;
/// `SCALE_PARAM_M2_212_PRED`
pub const SCALE_PARAM_M2_212_PRED: i32 = 3;
/// `SCALE_DATA_APPLY_M2`: scaling of the spectral data after applying M2
pub const SCALE_DATA_APPLY_M2: i32 = 1;
/// `SCALE_DATA_APPLY_M2_PC`: applying M2 with phase coding needs 2 bits headroom
pub const SCALE_DATA_APPLY_M2_PC: i32 = 2;

/// `N_CLD`
const N_CLD: usize = 31;
/// `N_IPD`
const N_IPD: usize = 16;

/// `SIN_IPD(a)`
#[inline]
fn sin_ipd(a: i32) -> FixpDbl {
    SIN_IPD_TAB[(a as usize) % N_IPD]
}

/// `COS_IPD(a)`: `sinIpd_tab[((a) + 4) & 15]`
#[inline]
fn cos_ipd(a: i32) -> FixpDbl {
    SIN_IPD_TAB[((a + 4) & 15) as usize]
}

/// `SpatialDecGetResidualIndex(self, row)`
///
/// Deviation: a tree configuration or row outside of `row2residual` gives -1.
pub fn spatial_dec_get_residual_index(self_: &SpatialDec, row: i32) -> i32 {
    ROW2RESIDUAL
        .get(self_.tree_config as usize)
        .and_then(|r| r.get(row as usize))
        .map_or(-1, |&v| v as i32)
}

/// `self->residualBands[SpatialDecGetResidualIndex(self, row)]` (deviation: an index outside of
/// the array reads 0).
pub(crate) fn residual_bands_of(self_: &SpatialDec, row: i32) -> i32 {
    let res = spatial_dec_get_residual_index(self_, row);
    self_.residual_bands.get(res as usize).map_or(0, |&v| v as i32)
}

/// `updateAlpha(self)`
fn update_alpha(self_: &mut SpatialDec) {
    let n_ch_in = (self_.num_input_channels.max(0) as usize).min(NUM_IN_CH);

    for ch in 0..n_ch_in {
        let alpha: FixpDbl = MAXVAL_DBL; // FL2FXCONST_DBL(1.0f)

        self_.arbdmx_alpha_prev__fdk[ch] = self_.arbdmx_alpha__fdk[ch];

        self_.arbdmx_alpha__fdk[ch] = alpha;
    }
}

/// `SpatialDecCalculateM1andM2(self, ps, frame)`
pub fn spatial_dec_calculate_m1_and_m2(
    self_: &mut SpatialDec,
    ps: i32,
    frame: &SpatialBsFrame,
) -> SacdecError {
    let err;

    if self_.arbitrary_downmix != 0 && ps == 0 {
        update_alpha(self_);
    }

    self_.p_activ_m2_param_bands = false;

    match self_.upmix_type {
        UPMIXTYPE_BYPASS | UPMIXTYPE_NORMAL => match self_.tree_config {
            TREE_212 => {
                err = spatial_dec_calculate_m1_and_m2_212(self_, ps, frame);
            }
            _ => {
                err = MPS_WRONG_TREECONFIG;
            }
        },
        _ => {
            err = MPS_WRONG_TREECONFIG;
        }
    }

    err
}

use crate::sac_bitdec::TREE_212;

/// `SpatialDecCalculateM1andM2_212(self, ps, frame)`
fn spatial_dec_calculate_m1_and_m2_212(
    self_: &mut SpatialDec,
    ps: i32,
    frame: &SpatialBsFrame,
) -> SacdecError {
    let err = MPS_OK;

    let mut h11re = [0 as FixpDbl; MAX_PARAMETER_BANDS];
    let mut h12re = [0 as FixpDbl; MAX_PARAMETER_BANDS];
    let mut h21re = [0 as FixpDbl; MAX_PARAMETER_BANDS];
    let mut h22re = [0 as FixpDbl; MAX_PARAMETER_BANDS];
    let mut h11im = [0 as FixpDbl; MAX_PARAMETER_BANDS];
    let mut h21im = [0 as FixpDbl; MAX_PARAMETER_BANDS];

    let phase_coding = self_.phase_coding;

    match phase_coding {
        1 => {
            // phase coding: yes; residuals: no
            let rb = self_.residual_bands[0] as i32;
            param2umx_ps_ipd_opd__fdk(
                self_, frame, &mut h11re, &mut h12re, &mut h21re, &mut h22re, None, None, 0, ps, rb,
            );
        }
        3 => {
            // phase coding: yes; residuals: yes
            let rb = self_.residual_bands[0] as i32;
            param2umx_prediction__fdk(
                self_,
                &mut h11re,
                Some(&mut h11im),
                &mut h12re,
                &mut h21re,
                Some(&mut h21im),
                &mut h22re,
                0,
                ps,
                rb,
            );
        }
        _ => {
            if self_.residual_coding != 0 {
                // phase coding: no; residuals: yes
                let rb = self_.residual_bands[0] as i32;
                param2umx_prediction__fdk(
                    self_, &mut h11re, None, &mut h12re, &mut h21re, None, &mut h22re, 0, ps, rb,
                );
            } else {
                // phase coding: no; residuals: no
                param2umx_ps__fdk(
                    self_, &mut h11re, &mut h12re, &mut h21re, &mut h22re, None, None, 0, ps, 0,
                );
            }
        }
    }

    // numParameterBands <= MAX_PARAMETER_BANDS (from the frequency resolution tables).
    let npb = (self_.num_parameter_bands.max(0) as usize).min(MAX_PARAMETER_BANDS);
    self_.m2_real__fdk[0][0][..npb].copy_from_slice(&h11re[..npb]);
    self_.m2_real__fdk[0][1][..npb].copy_from_slice(&h12re[..npb]);
    self_.m2_real__fdk[1][0][..npb].copy_from_slice(&h21re[..npb]);
    self_.m2_real__fdk[1][1][..npb].copy_from_slice(&h22re[..npb]);
    if phase_coding == 3 {
        for pb in 0..npb {
            self_.m2_imag__fdk[0][0][pb] = h11im[pb];
            self_.m2_imag__fdk[1][0][pb] = h21im[pb];
            self_.m2_imag__fdk[0][1][pb] = 0; // H12im[pb];
            self_.m2_imag__fdk[1][1][pb] = 0; // H22im[pb];
        }
    }

    if self_.phase_coding == 1 {
        // INPUT: PhaseLeft, PhaseRight, (opdLeftState, opdRightState)
        spatial_dec_smooth_opd(self_, frame, ps);
    }

    err
}

/// `self->ott<X>__FDK[ottBoxIndx][parameterSetIndx]` (deviation: indices outside of the
/// arrays, which the library never uses, give the first entries).
#[inline]
fn param_row(
    a: &[ParamSets; NUM_OTT],
    ott_box_indx: i32,
    parameter_set_indx: i32,
) -> &[i8; MAX_PARAMETER_BANDS] {
    let b = (ott_box_indx.max(0) as usize).min(NUM_OTT - 1);
    let s = (parameter_set_indx.max(0) as usize).min(MAX_PARAMETER_SETS - 1);
    &a[b][s]
}

/// `param2UMX_PS_Core__FDK(cld, icc, numOttBands, resBands, H11, H12, H21, H22, c_l, c_r)`
fn param2umx_ps_core__fdk(
    cld: &[i8; MAX_PARAMETER_BANDS],
    icc: &[i8; MAX_PARAMETER_BANDS],
    num_ott_bands: i32,
    res_bands: i32,
    h11: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h12: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h21: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h22: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    c_l: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    c_r: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
) {
    let n = (num_ott_bands.max(0) as usize).min(MAX_PARAMETER_BANDS);

    if let (Some(c_l), Some(c_r)) = (c_l, c_r) {
        for band in 0..n {
            let (cu, cl) = spatial_dequant_get_cld_values(cld[band] as i32);
            c_l[band] = cu;
            c_r[band] = cl;
        }
    }

    fdk_assert!(res_bands == 0);
    for band in 0..n {
        // compute mixing variables: the indices are dequantized table indices (CLD 0..=30, ICC
        // 0..=7); deviation: other values read 0.
        let idx1 = cld[band] as i32;
        let idx2 = icc[band] as i32;
        let h = |t: &[[FixpDbl; 8]; 31], i: i32, j: i32| {
            t.get(i as usize).and_then(|r| r.get(j as usize)).copied().unwrap_or(0)
        };
        h11[band] = fx_cfg2fx_dbl(h(&H11_NC, idx1, idx2));
        h21[band] = fx_cfg2fx_dbl(h(&H11_NC, 30 - idx1, idx2));
        h12[band] = fx_cfg2fx_dbl(h(&H12_NC, idx1, idx2));
        h22[band] = fx_cfg2fx_dbl(h(&H12_NC, 30 - idx1, idx2).wrapping_neg());
    }
}

/// `param2UMX_PS__FDK(self, H11, H12, H21, H22, c_l, c_r, ottBoxIndx, parameterSetIndx,
/// residualBands)`
fn param2umx_ps__fdk(
    self_: &SpatialDec,
    h11: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h12: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h21: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h22: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    c_l: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    c_r: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    ott_box_indx: i32,
    parameter_set_indx: i32,
    residual_bands: i32,
) {
    let nob = self_.num_ott_bands[(ott_box_indx.max(0) as usize).min(NUM_OTT - 1)];
    param2umx_ps_core__fdk(
        param_row(&self_.ott_cld__fdk, ott_box_indx, parameter_set_indx),
        param_row(&self_.ott_icc__fdk, ott_box_indx, parameter_set_indx),
        nob,
        residual_bands,
        h11,
        h12,
        h21,
        h22,
        c_l,
        c_r,
    );

    for band in band_range(nob, self_.num_parameter_bands) {
        h11[band] = 0;
        h21[band] = 0;
        h12[band] = 0;
        h22[band] = 0;
    }
}

/// The band range `start..stop` within `MAX_PARAMETER_BANDS`.
#[inline]
fn band_range(start: i32, stop: i32) -> core::ops::Range<usize> {
    let s = start.clamp(0, MAX_PARAMETER_BANDS as i32) as usize;
    let e = stop.clamp(0, MAX_PARAMETER_BANDS as i32) as usize;
    s..e.max(s)
}

/// `calculateOpd(self, ottBoxIndx, parameterSetIndx, opd)`
fn calculate_opd(
    self_: &SpatialDec,
    ott_box_indx: i32,
    parameter_set_indx: i32,
    opd: &mut [FixpDbl; 2 * MAX_PARAMETER_BANDS],
) {
    let cld_row = param_row(&self_.ott_cld__fdk, ott_box_indx, parameter_set_indx);
    let ipd_row = param_row(&self_.ott_ipd__fdk, ott_box_indx, parameter_set_indx);
    let icc_row = param_row(&self_.ott_icc__fdk, ott_box_indx, parameter_set_indx);

    for band in 0..(self_.num_ott_bands_ipd.max(0) as usize).min(MAX_PARAMETER_BANDS) {
        let idx_cld = cld_row[band] as i32;
        let idx_ipd = ipd_row[band] as i32;
        let idx_icc = icc_row[band] as i32;

        // Dequantized table indices (deviation: other values read 0).
        let ipd = fx_cfg2fx_dbl(DEQUANT_IPD__FDK.get(idx_ipd as usize).copied().unwrap_or(0));
        let cld = spatial_dequant_get_cld2_values(idx_cld);

        // ipd(idxIpd==8) == PI
        if (cld == 0 && idx_ipd == 8) || idx_ipd == 0 {
            opd[2 * band] = 0;
        } else {
            fdk_assert!(idx_ipd > 0);
            opd[2 * band] = DEQUANT_IPD_CLD_ICC_SPLIT_ANGLE__FDK
                .get((idx_ipd - 1) as usize)
                .and_then(|t| t.get(idx_cld as usize))
                .and_then(|t| t.get(idx_icc as usize))
                .copied()
                .unwrap_or(0);
        }
        opd[2 * band + 1] = opd[2 * band].wrapping_sub(ipd);
    }
}

/// `wrapPhase(phase)`: wraps a phase in rad to the range `0 <= x < 2*pi`.
fn wrap_phase(mut phase: FixpDbl) -> FixpDbl {
    while phase < 0 {
        phase = phase.wrapping_add(PIX2__IPD);
    }
    while phase >= PIX2__IPD {
        phase = phase.wrapping_sub(PIX2__IPD);
    }
    fdk_assert!(phase >= 0 && phase < PIX2__IPD);

    phase
}

/// `param2UMX_PS_IPD_OPD__FDK(self, frame, H11, H12, H21, H22, c_l, c_r, ottBoxIndx,
/// parameterSetIndx, residualBands)`
fn param2umx_ps_ipd_opd__fdk(
    self_: &mut SpatialDec,
    frame: &SpatialBsFrame,
    h11: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h12: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h21: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h22: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    c_l: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    c_r: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    ott_box_indx: i32,
    parameter_set_indx: i32,
    residual_bands: i32,
) {
    let mut opd = [0 as FixpDbl; 2 * MAX_PARAMETER_BANDS];
    let num_ott_bands = self_.num_ott_bands[(ott_box_indx.max(0) as usize).min(NUM_OTT - 1)];

    let num_ipd_bands = if frame.phase_mode != 0 { self_.num_ott_bands_ipd } else { 0 };

    fdk_assert!(self_.residual_coding == 0);

    param2umx_ps_core__fdk(
        param_row(&self_.ott_cld__fdk, ott_box_indx, parameter_set_indx),
        param_row(&self_.ott_icc__fdk, ott_box_indx, parameter_set_indx),
        num_ott_bands,
        residual_bands,
        h11,
        h12,
        h21,
        h22,
        c_l,
        c_r,
    );
    for band in band_range(num_ott_bands, self_.num_parameter_bands) {
        h11[band] = 0;
        h21[band] = 0;
        h12[band] = 0;
        h22[band] = 0;
    }

    if frame.phase_mode != 0 {
        calculate_opd(self_, ott_box_indx, parameter_set_indx, &mut opd);

        for band in band_range(0, num_ipd_bands) {
            self_.phase_left__fdk[band] = wrap_phase(opd[2 * band]);
            self_.phase_right__fdk[band] = wrap_phase(opd[2 * band + 1]);
        }
    }

    for band in band_range(num_ipd_bands, num_ott_bands) {
        self_.phase_left__fdk[band] = 0;
        self_.phase_right__fdk[band] = 0;
    }
}

/// `MAX_WEIGHT`
const MAX_WEIGHT: f32 = 1.2;

/// `param2UMX_Prediction_Core__FDK(H11re, H11im, H12re, H12im, H21re, H21im, H22re, H22im,
/// cldIdx, iccIdx, ipdIdx, band, numOttBandsIPD, resBands)` (`H12im` and `H22im` are always
/// `NULL`). Returns `(H11re, H12re, H21re, H22re, Some((H11im, H21im)))`, the imaginary parts
/// only if `with_im`; the C function does not write the outputs of the absent pointers.
fn param2umx_prediction_core__fdk(
    with_im: bool,
    cld_idx: i32,
    icc_idx: i32,
    ipd_idx: i32,
    band: i32,
    num_ott_bands_ipd: i32,
    res_bands: i32,
) -> (FixpDbl, FixpDbl, FixpDbl, FixpDbl, Option<(FixpDbl, FixpDbl)>) {
    let (h11re, h12re, h21re, h22re);
    let mut im = None;

    // Dequantized table indices (cldIdx 0..=30, iccIdx 0..=7, ipdIdx 0..=15); deviation: other
    // values are wrapped into the tables.
    let cld_idx_u = (cld_idx.max(0) as usize).min(N_CLD - 1);
    let icc_idx_u = (icc_idx & 7) as usize;

    if band < num_ott_bands_ipd && cld_idx == 15 && icc_idx == 0 && ipd_idx == 8 {
        let gain: FixpDbl = fl2fxconst_dbl((0.5f32 / MAX_WEIGHT) as f64) >> SCALE_PARAM_M2_212_PRED;
        h11re = gain;
        if band < res_bands {
            h21re = gain;
            h12re = gain;
            h22re = gain.wrapping_neg();
        } else {
            h21re = gain.wrapping_neg();
            h12re = 0;
            h22re = 0;
        }
        if with_im {
            im = Some((0, 0));
        }
    } else {
        let one_m: FixpDbl = MAXVAL_DBL;
        let one_e = 0;
        // iidLin = sqrt(cld);
        let iid_lin_m = SQRT_CLD_M[cld_idx_u];
        let iid_lin_e = SQRT_CLD_E[cld_idx_u] as i32;
        // iidLin2 = cld;
        let iid_lin2_m = CLD_M[cld_idx_u];
        // sqrt_CLD_e[cldIdx] << 1: a left shift of a negative value, a plain shift in both
        // builds.
        let iid_lin2_e = (SQRT_CLD_E[cld_idx_u] as i32).wrapping_shl(1);
        // iidLin21 = iidLin2 + 1.0f;
        let mut iid_lin21_e = 0;
        let mut iid_lin21_m = f_add_norm(iid_lin2_m, iid_lin2_e, one_m, one_e, &mut iid_lin21_e);
        // iidIcc2 = iidLin * icc * 2.0f;
        let icc: FixpCfg = DEQUANT_ICC__FDK[icc_idx_u];
        let iid_icc2_e = iid_lin_e + 1;
        let iid_icc2_m = f_mult(iid_lin_m, icc);

        let ipd_sel = if band < num_ott_bands_ipd { ipd_idx } else { 0 };
        let cos_ipd = cos_ipd(ipd_sel);
        let sin_ipd = sin_ipd(ipd_sel & 15);

        // temp = iidLin21 + iidIcc2 * cosIpd;
        let mut temp_e = 0;
        let temp_m = f_add_norm(
            iid_lin21_m,
            iid_lin21_e,
            f_mult(iid_icc2_m, cos_ipd),
            iid_icc2_e,
            &mut temp_e,
        );

        // calculate 1/temp needed later
        let mut inv_temp_e = temp_e;
        let inv_temp_m = inv_fixp_e(temp_m, &mut inv_temp_e);

        // 1/weight = sqrt(temp) * 1/sqrt(iidLin21)
        let (mut sqrt_temp_m, sqrt_temp_e);
        if temp_e & 1 != 0 {
            sqrt_temp_m = temp_m >> 1;
            sqrt_temp_e = (temp_e + 1) >> 1;
        } else {
            sqrt_temp_m = temp_m;
            sqrt_temp_e = temp_e >> 1;
        }
        sqrt_temp_m = sqrt_fixp(sqrt_temp_m);
        if iid_lin21_e & 1 != 0 {
            iid_lin21_e += 1;
            iid_lin21_m >>= 1;
        }
        // weight_[m,e] is actually 1/weight in the next few lines
        let mut weight_e = 0;
        let mut weight_m = inv_sqrt_norm2(iid_lin21_m, &mut weight_e);
        weight_e -= iid_lin21_e >> 1;
        weight_m = f_mult(sqrt_temp_m, weight_m);
        weight_e += sqrt_temp_e;
        let scale = f_norm(weight_m);
        weight_m = scale_value(weight_m, scale);
        weight_e -= scale;
        // weight = 0.5 * max(1/weight, 1/maxWeight)
        if weight_e < 0
            || (weight_e == 0 && weight_m < fl2fxconst_dbl((1.0f32 / MAX_WEIGHT) as f64))
        {
            weight_m = fl2fxconst_dbl((1.0f32 / MAX_WEIGHT) as f64);
            weight_e = 0;
        }
        weight_e -= 1;

        {
            // alphaRe = (1.0f - iidLin2) / temp;
            let mut alpha_re_e = 0;
            let mut alpha_re_m =
                f_add_norm(one_m, one_e, iid_lin2_m.wrapping_neg(), iid_lin2_e, &mut alpha_re_e);
            alpha_re_m = f_mult(alpha_re_m, inv_temp_m);
            alpha_re_e += inv_temp_e;

            // H11re = weight - alphaRe * weight;
            // H21re = weight + alphaRe * weight;
            let accu_m = f_mult(alpha_re_m, weight_m);
            let accu_e = alpha_re_e + weight_e;

            {
                let mut accu2_e = 0;
                let accu2_m =
                    f_add_norm(weight_m, weight_e, accu_m.wrapping_neg(), accu_e, &mut accu2_e);
                h11re = scale_value(accu2_m, accu2_e - SCALE_PARAM_M2_212_PRED);

                let accu2_m = f_add_norm(weight_m, weight_e, accu_m, accu_e, &mut accu2_e);
                h21re = scale_value(accu2_m, accu2_e - SCALE_PARAM_M2_212_PRED);
            }

            if with_im {
                // alphaIm = -iidIcc2 * sinIpd / temp;
                let mut alpha_im_m = f_mult(iid_icc2_m.wrapping_neg(), sin_ipd);
                alpha_im_m = f_mult(alpha_im_m, inv_temp_m);
                let alpha_im_e = iid_icc2_e + inv_temp_e;
                // H11im = -alphaIm * weight;
                // H21im =  alphaIm * weight;
                let mut accu_m = f_mult(alpha_im_m, weight_m);
                let accu_e = alpha_im_e + weight_e;

                accu_m = scale_value(accu_m, accu_e - SCALE_PARAM_M2_212_PRED);
                im = Some((accu_m.wrapping_neg(), accu_m));
            }
        }

        if band < res_bands {
            let weight = scale_value(weight_m, weight_e - SCALE_PARAM_M2_212_PRED);
            h12re = weight;
            h22re = weight.wrapping_neg();
        } else {
            // beta = 2.0f * iidLin * (float) sqrt(1.0f - icc * icc) * weight / temp;
            let mut beta_m = fx_sgl2fx_dbl(SQRT_ONE_MINUS_ICC2[icc_idx_u]);
            let mut beta_e = 1; // multiplication with 2.0f
            beta_m = f_mult(beta_m, weight_m);
            beta_e += weight_e;
            beta_m = f_mult(beta_m, iid_lin_m);
            beta_e += iid_lin_e;
            beta_m = f_mult(beta_m, inv_temp_m);
            beta_e += inv_temp_e;

            beta_m = scale_value(beta_m, beta_e - SCALE_PARAM_M2_212_PRED);
            h12re = beta_m;
            h22re = beta_m.wrapping_neg();
        }
    }

    (h11re, h12re, h21re, h22re, im)
}

/// `param2UMX_Prediction__FDK(self, H11re, H11im, H12re, H12im, H21re, H21im, H22re, H22im,
/// ottBoxIndx, parameterSetIndx, resBands)` (`H12im` and `H22im` are always `NULL`).
fn param2umx_prediction__fdk(
    self_: &SpatialDec,
    h11re: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    mut h11im: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    h12re: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    h21re: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    mut h21im: Option<&mut [FixpDbl; MAX_PARAMETER_BANDS]>,
    h22re: &mut [FixpDbl; MAX_PARAMETER_BANDS],
    ott_box_indx: i32,
    parameter_set_indx: i32,
    res_bands: i32,
) {
    let cld = param_row(&self_.ott_cld__fdk, ott_box_indx, parameter_set_indx);
    let icc = param_row(&self_.ott_icc__fdk, ott_box_indx, parameter_set_indx);
    let ipd = param_row(&self_.ott_ipd__fdk, ott_box_indx, parameter_set_indx);
    let with_im = h11im.is_some() && h21im.is_some();

    for band in band_range(0, self_.num_parameter_bands) {
        let cld_idx = cld[band] as i32;
        let icc_idx = icc[band] as i32;
        let ipd_idx = ipd[band] as i32;
        let (r11, r12, r21, r22, im) = param2umx_prediction_core__fdk(
            with_im,
            cld_idx,
            icc_idx,
            ipd_idx,
            band as i32,
            self_.num_ott_bands_ipd,
            res_bands,
        );
        h11re[band] = r11;
        h12re[band] = r12;
        h21re[band] = r21;
        h22re[band] = r22;
        if let Some((i11, i21)) = im {
            if let Some(h) = h11im.as_deref_mut() {
                h[band] = i11;
            }
            if let Some(h) = h21im.as_deref_mut() {
                h[band] = i21;
            }
        }
    }
}

/// `initM1andM2(self, initStatesFlag, configChanged)`
pub fn init_m1_and_m2(
    self_: &mut SpatialDec,
    init_states_flag: i32,
    config_changed: i32,
) -> SacdecError {
    let err = MPS_OK;

    self_.b_overwrite_m1m2prev = (config_changed != 0 && init_states_flag == 0) as i32;

    self_.num_m2rows = self_.num_output_channels;

    if init_states_flag != 0 {
        // numM2rows <= 2 and numVChannels <= 2 for the 212 tree.
        let rows = (self_.num_m2rows.max(0) as usize).min(NUM_OUT_CH);
        let cols = (self_.num_v_channels.max(0) as usize).min(NUM_V_CH);
        for i in 0..rows {
            for j in 0..cols {
                for k in 0..MAX_PARAMETER_BANDS {
                    self_.m2_real__fdk[i][j][k] = 0;
                    self_.m2_real_prev__fdk[i][j][k] = 0;
                }
            }
        }
    }

    err
}
